import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [n, q] = lines[0].split(" ").map(Number);
const a = lines[1].split(" ").map(Number);

// 葉が size 個の完全二分木。tree[1] が根、tree[size + i] が Ai
let size = 1;
while (size < n) size <<= 1;
const tree = new Array(2 * size).fill(Infinity);
for (let i = 0; i < n; i++) tree[size + i] = a[i];
for (let i = size - 1; i >= 1; i--) tree[i] = Math.min(tree[2 * i], tree[2 * i + 1]);

function update(i: number, x: number): void {
  i += size;
  tree[i] = x;
  // 親をたどって最小値を更新する
  for (i >>= 1; i >= 1; i >>= 1) tree[i] = Math.min(tree[2 * i], tree[2 * i + 1]);
}

// 半開区間 [l, r) の最小値
function query(l: number, r: number): number {
  let res = Infinity;
  for (l += size, r += size; l < r; l >>= 1, r >>= 1) {
    if (l & 1) res = Math.min(res, tree[l++]);
    if (r & 1) res = Math.min(res, tree[--r]);
  }
  return res;
}

const out: number[] = [];
for (let k = 0; k < q; k++) {
  const [t, x, y] = lines[2 + k].split(" ").map(Number);
  if (t === 1) update(x - 1, y);
  else out.push(query(x - 1, y));
}
console.log(out.join("\n"));
